type repositoryHandler struct {
	singleflight.Group
}

type httpStatusError struct {
	code int
	err  error
}

func (e *httpStatusError) Error() string { return e.err.Error() }
func (e *httpStatusError) Unwrap() error { return e.err }

func httpErr(code int, err error) *httpStatusError {
	return &httpStatusError{code: code, err: err}
}

func NewRepositoryHandler() *repositoryHandler {
	// warm up the badges cache - we can already initialize the config
	_ = config.GetNeededObservers()

	return &repositoryHandler{
		Group: singleflight.Group{},
	}
}

func runChecks(ctx context.Context, enabledChecks []observe.Observer, repositoryURL string) ([]observe.Observation, error) {
	// get the correct git client
	client, err := config.GetMatchingGitClient(repositoryURL)
	if err != nil {
		return nil, err
	}

	observer := observe.NewParallelObserver(
		enabledChecks...,
	)
	// run the checks
	observations, err := observer.RunObservers(ctx, client, repositoryURL, observe.AdditionalInputData{
		CosignAttestClient: common.NewCosignAttestationClient(),
	})
	if err != nil {
		return nil, err
	}

	return observations, nil
}
